const botao = document.querySelector('#guardar');

function aoClicar(event) {
  console.log('Botão clicado, elemento:', event.currentTarget);
}

botao.addEventListener('click', aoClicar);

// mais tarde, remove exatamente a mesma função registada acima
botao.removeEventListener('click', aoClicar);

// um listener que se remove sozinho depois de disparar uma vez
botao.addEventListener('click', () => {
  console.log('Isto só corre na primeira vez');
}, { once: true });

document.querySelector('#menu').addEventListener('click', (event) => {
  console.log('target:', event.target);            // elemento exato clicado, ex: um <span> dentro do link
  console.log('currentTarget:', event.currentTarget); // sempre o <ul id="menu">, onde o listener foi registado
});

document.querySelector('#formulario-login').addEventListener('submit', (event) => {
  event.preventDefault(); // impede o recarregamento da página
  console.log('Dados validados no lado do cliente antes de enviar');
});

const exterior = document.querySelector('#exterior');
const interior = document.querySelector('#interior');

exterior.addEventListener('click', () => console.log('1 - exterior (captura)'), { capture: true });
interior.addEventListener('click', () => console.log('2 - interior (alvo)'));
exterior.addEventListener('click', () => console.log('3 - exterior (bubbling)'));

// ao clicar em #interior, a consola mostra, por esta ordem:
// 1 - exterior (captura)
// 2 - interior (alvo)
// 3 - exterior (bubbling)

const lista = document.querySelector('#lista-tarefas');

lista.addEventListener('click', (event) => {
  const botaoRemover = event.target.closest('.remover');
  if (!botaoRemover) return; // o clique não foi num botão de remover

  const item = botaoRemover.closest('li');
  item.remove();
});

// itens adicionados depois já funcionam, sem registar nenhum novo listener
const novoItem = document.createElement('li');
novoItem.innerHTML = 'Comprar leite <button class="remover">Remover</button>';
lista.appendChild(novoItem);

const campoBusca = document.querySelector('#busca');
const formulario = document.querySelector('#formulario-busca');

campoBusca.addEventListener('input', (event) => {
  console.log('Valor atual:', event.target.value);
});

campoBusca.addEventListener('keydown', (event) => {
  if (event.key === 'Escape') {
    campoBusca.value = '';
  }
});

formulario.addEventListener('submit', (event) => {
  event.preventDefault();
  const termo = campoBusca.value.trim();
  if (termo) {
    console.log('A pesquisar por:', termo);
  }
});

const controlador = new AbortController();

document.querySelector('#abrir-modal').addEventListener('click', abrirModal, {
  signal: controlador.signal,
});
document.addEventListener('keydown', fecharComEscape, {
  signal: controlador.signal,
});

// mais tarde, ao destruir o componente, remove os dois listeners de uma só vez
controlador.abort();

