let cliques = 0;
const botao = document.querySelector('#btn-contar');
const paragrafo = document.querySelector('#contagem');

botao.addEventListener('click', () => {
  cliques++;
  paragrafo.textContent = `Cliques: ${cliques}`;
});

const formulario = document.querySelector('#form-contacto');
const campoEmail = document.querySelector('#email');
const erro = document.querySelector('#erro');

formulario.addEventListener('submit', (event) => {
  event.preventDefault();

  const valor = campoEmail.value.trim();

  if (!valor.includes('@')) {
    erro.textContent = 'Email inválido';
    return;
  }

  erro.textContent = '';
  console.log('Formulário válido');
});

const lista = document.querySelector('#tarefas');
const botaoAdicionar = document.querySelector('#adicionar');

botaoAdicionar.addEventListener('click', () => {
  const item = document.createElement('li');
  item.innerHTML = 'Nova tarefa <button class="concluir">Concluir</button>';
  lista.appendChild(item);
});

lista.addEventListener('click', (event) => {
  const botaoConcluir = event.target.closest('.concluir');
  if (!botaoConcluir) return;

  const tarefa = botaoConcluir.closest('li');
  tarefa.classList.add('feita');
});

const botaoMenu = document.querySelector('#menu-toggle');
const menu = document.querySelector('#menu-opcoes');

botaoMenu.addEventListener('click', (event) => {
  event.stopPropagation();
  menu.hidden = !menu.hidden;
});

menu.addEventListener('click', (event) => {
  event.stopPropagation();
});

document.addEventListener('click', () => {
  if (!menu.hidden) {
    menu.hidden = true;
  }
});
